CREATE POLICY "own lesson files read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'lessons' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "own lesson files insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'lessons' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "own lesson files delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'lessons' AND auth.uid()::text = (storage.foldername(name))[1]);